/**
 * Candidate string -> key in TEMPLATE_LOGOS.
 *
 * The candidates are a template's slug and the last segment of its image name,
 * both lowercased, so a user template deploying `redis:7` gets the Redis mark
 * without anyone maintaining a list of their slugs.
 */
const ALIASES: Record<string, string> = {
  "adminer": "adminer",
  "apache": "apache",
  "grafana": "grafana",
  "httpd": "apache",
  "mariadb": "mysql",
  "minio": "minio",
  "mongo": "mongodb",
  "mongodb": "mongodb",
  "mysql": "mysql",
  "n8n": "n8n",
  "nginx": "nginx",
  "node": "nodedotjs",
  "node-app": "nodedotjs",
  "nodedotjs": "nodedotjs",
  "postgres": "postgresql",
  "postgresql": "postgresql",
  "prometheus": "prometheus",
  "python": "python",
  "python-app": "python",
  "rabbitmq": "rabbitmq",
  "redis": "redis",
  "traefik": "traefikproxy",
  "traefikproxy": "traefikproxy",
  "uptime-kuma": "uptimekuma",
  "uptimekuma": "uptimekuma",
  "whoami": "traefikproxy",
  "wordpress": "wordpress",
};

/**
 * The mark for a template, or null when we have none for it.
 *
 * Tries the template's slug first, then the image name. Returns null rather
 * than guessing, so an unknown template falls back to its own icon instead of
 * wearing some other product's logo.
 */
export function logoFor(template: {
  slug?: string | null;
  spec?: { image?: string | null } | null;
}): TemplateLogo | null {
  const candidates: string[] = [];
  if (template.slug) candidates.push(template.slug.toLowerCase());
  const image = template.spec?.image;
  if (image) {
    // Drop the digest, then take the last path segment, then drop the tag. In
    // that order: a registry host carries its own colon (`host:5000/team/app`),
    // so splitting the tag off first would throw the repository away with it.
    const withoutDigest = image.split('@')[0];
    const repo = withoutDigest.split('/').pop() ?? '';
    const name = repo.split(':')[0];
    if (name) candidates.push(name.toLowerCase());
  }

  for (const candidate of candidates) {
    const key = ALIASES[candidate] ?? candidate;
    const logo = TEMPLATE_LOGOS[key];
    if (logo) return logo;
  }
  return null;
}
